style.css:
@-moz-document url-prefix("https://open.spotify.com") {
/* Base background and text color */
  body, html, * {
    background-color: #ADD8E6 !important;
    color: #00008B !important;
    border-color: #ADD8E6 !important;
    box-shadow: none !important;
  }

  /* Major containers */
  .Root__top-bar, .Root__nav-bar, .Root__main-view,
  .Root__now-playing-bar, .main-view-container,
  header, footer, .main-container, .main-trackList {
    background-color: #ADD8E6 !important;
    border-color: #ADD8E6 !important;
  }

  /* Buttons and links */
  button, a {
    background-color: #ADD8E6 !important;
    color: #00008B !important;
    border: 1px solid #ADD8E6 !important;
  }

  /* Hover effects */
  button:hover, a:hover {
    background-color: #87CEFA !important;
    color: #000066 !important;
    border-color: #87CEFA !important;
  }

  /* Input fields */
  input, textarea, select {
    background-color: #ADD8E6 !important;
    color: #00008B !important;
    border: 1px solid #ADD8E6 !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    background-color: #ADD8E6 !important;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #00008B !important;
  }

  /* Remove borders and shadows from all */
  * {
    border: 1px solid #ADD8E6 !important;
    box-shadow: none !important;
  }
}
